export function fmtPp(n: number, d = 0): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toFixed(d)} pp`;
}

export function fmtInt(n: number): string {
  return n.toLocaleString("en-US");
}

export function strategicFor(
  bloc: StrategicVintageRow["bloc"] | "All"
): StrategicVintageRow[] {
