        .sort((a, b) => b.value - a.value),
    [deltas]
  );

  const dumbbell = useMemo(
    () =>
      strategicRows.map((r) => ({
        key: r.shortLabel,
        label: r.shortLabel,
        prior: r.priorPct,
        neu: r.newPct,
      })),
    [strategicRows]
