"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  LineChart,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  GREEN_SUBSIDY_SHARE,
  HEADLINE,
  INSTRUMENT_PERSISTENCE,
  SELECTIVE_ACTIVITY,
  SOURCE_NOTE,
  SOURCES,
  STRATEGIC_PATH,
  STRATEGIC_SUBSIDY_SHARE,
  STRATEGIC_VS_GREEN,
  SUBSIDY_FOLLOW_RATES,
  deltasFor,
  fmtInt,
  fmtPct,
  fmtPp,
  strategicFor,
  type DeltaBarRow,
  type StrategicVintageRow,
} from "@/data/fiscal-industrial-policy-update-2026q3-data";

// viz-types: diverging-delta-bar, strategic-path-line, dumbbell-strategic, green-grouped-bar, follow-range-area, strategic-green-scatter | layout: default
// viz-plan: vintage ?? bars; CN/EU/US strategic path; prior???new dumbbell; green catch-up bars; subsidy-follow band; scatter; bloc + delta-group controls

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

type BlocFilter = StrategicVintageRow["bloc"] | "All";
type DeltaGroup = DeltaBarRow["group"] | "All";

const COLORS = {
  prior: "#94a3b8",
  neu: "#0f766e",
  up: "#be123c",
  down: "#0369a1",
  china: "#dc2626",
  eu: "#2563eb",
  us: "#7c3aed",
  green: "#ca8a04",
  band: "#0d9488",
  export: "#c2410c",
  importBar: "#64748b",
  subsidy: "#4f46e5",
};

export function FiscalIndustrialPolicyUpdate2026q3Dashboard() {
  const [bloc, setBloc] = useState<BlocFilter>("All");
  const [deltaGroup, setDeltaGroup] = useState<DeltaGroup>("All");

  const strategicRows = useMemo(() => strategicFor(bloc), [bloc]);
  const deltas = useMemo(() => deltasFor(deltaGroup), [deltaGroup]);

  const deltaBars = useMemo(
    () =>
      [...deltas]
        .map((d) => ({
          id: d.id,
          label: d.label,
          value: d.delta,
          fill: d.delta >= 0 ? COLORS.up : COLORS.down,
          priorValue: d.priorValue,
          newValue: d.newValue,
          priorLabel: d.priorLabel,
          newLabel: d.newLabel,
          unit: d.unit,
        }))
        .sort((a, b) => b.value - a.value),
    [deltas]
  );

  const dumbbell = useMemo(
    () =>
      strategicRows.map((r) => ({
        key: r.shortLabel,
        label: r.shortLabel,
        prior: r.priorPct,
        neu: r.newPct,
      })),
    [strategicRows]
  );

  const pathChart = useMemo(
    () =>
      STRATEGIC_PATH.map((r) => ({
        window: r.window,
        China: r.china,
        EU: r.eu,
        US: r.us,
      })),
    []
  );

  const greenChart = useMemo(
    () =>
      GREEN_SUBSIDY_SHARE.map((r) => ({
        bloc: r.shortLabel,
        early: r.earlyPct,
        late: r.latePct,
      })),
    []
  );

  const followChart = useMemo(
    () =>
      SUBSIDY_FOLLOW_RATES.map((r) => ({
        period: r.period,
        low: r.lowPct,
        high: r.highPct,
        mid: r.midPct,
        span: r.highPct - r.lowPct,
      })),
    []
  );

  const persistChart = useMemo(
    () =>
      INSTRUMENT_PERSISTENCE.map((r) => ({
        instrument: r.shortLabel,
        early: r.earlyPct,
        late: r.latePct,
      })),
    []
  );

  const activityChart = useMemo(
    () =>
      SELECTIVE_ACTIVITY.map((r) => ({
        period: r.period,
        actions: r.annualActions,
        label: r.label,
