          US strategic subsidy targeting {fmtPct(HEADLINE.usStrategicPriorPct)} ???{" "}
          {fmtPct(HEADLINE.usStrategicNewPct)} ({fmtPp(HEADLINE.usStrategicDeltaPp)})
