            {(
              [
                ["All", "All"],
                ["strategic", "Strategic"],
                ["activity", "Activity"],
                ["green", "Green"],
                ["interaction", "Interaction"],
              ] as const
            ).map(([id, label]) => (
              <button
                key={id}
                type="button"
                onClick={() => setDeltaGroup(id)}
                className={`rounded-md px-3 py-1.5 text-xs font-semibold transition ${
                  deltaGroup === id
                    ? "bg-rose-800 text-white shadow-sm"
                    : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                }`}
              >
                {label}
              </button>
            ))}
